import {createCafeScene} from './cafe-scene.js';
import {cafeMenu,cafeSeats} from './cafe-catalog.js';
import {newId} from './cloud.js';
export function createCafeUI({cloud,toast,beforeOpen,onClose}){
 const link=document.createElement('link');link.rel='stylesheet';link.href='./cafe.css';document.head.append(link);
 const entry=document.createElement('button');entry.className='pill';entry.textContent='海边咖啡馆';entry.id='visit-cafe';(document.querySelector('#world-menu .menu-items')||document.querySelector('nav')).append(entry);
 const shell=document.createElement('section');shell.id='cafe';shell.hidden=true;shell.setAttribute('aria-label','海边咖啡馆');shell.innerHTML='<div class="cafe-stage"></div><header class="cafe-top"><button data-cafe="leave">‹ 回家</button><div><strong>海风来信</strong><small class="cafe-time"></small></div><span class="cafe-count"></span></header><div class="cafe-actions" hidden></div><div class="cafe-note" role="status"></div><footer class="cafe-bottom"><button data-cafe="island">海岛</button><button data-cafe="terrace">露台</button><button data-cafe="inside">咖啡馆</button><button data-cafe="drinks">点单</button><button data-cafe="desserts">甜品</button></footer>';document.body.append(shell);
 const actions=shell.querySelector('.cafe-actions'),note=shell.querySelector('.cafe-note');let scene=null,active=false,opening=false,busy=false,syncing=false,timer=null,epoch=0,data=null,pose={x:0,z:4.1,yaw:Math.PI},selection=null,pendingOrder=null,noteTimer=null,issued=0,accepted=0;
 const message=text=>{note.textContent=text;clearTimeout(noteTimer);noteTimer=setTimeout(()=>{note.textContent=''},5000)};
 function paint(value,sequence=++issued){if(sequence<accepted)return;accepted=sequence;shell.classList.toggle('cafe-night',value.sky.night);data=value;scene?.update(value);const mine=value.guests.find(g=>g.id===value.self);const t=new Date(value.sky.time).toLocaleTimeString('zh-CN',{timeZone:'Asia/Shanghai',hour:'2-digit',minute:'2-digit'});shell.querySelector('.cafe-time').textContent=`${t} · ${value.sky.weather==='rain'?'小雨':value.sky.night?'夜晚':'晴天'} · ${value.sky.temperature}°`;shell.querySelector('.cafe-count').textContent=`${value.guests.length} 位访客`;if(mine?.held&&!selection&&actions.hidden){show('<button data-cafe="eat">'+(cafeMenu.find(i=>i.id===mine.held.item)?.kind==='dessert'?'吃一口':'喝一口')+'</button>')};}
 function show(html){actions.innerHTML=html;actions.hidden=false}
 async function action(body){if(busy||!active)return null;busy=true;const token=epoch,sequence=++issued;try{const r=await cloud.cafe(body);if(token!==epoch)return null;paint(r,sequence);return r}catch(e){if(token===epoch)message(e.message||'连接中断，请稍后重试');return null}finally{if(token===epoch)busy=false}}
 async function sync(){if(!active||busy||syncing||document.hidden)return;syncing=true;const token=epoch,sequence=++issued;try{const r=await cloud.cafe({action:'sync',...pose});if(token===epoch)paint(r,sequence)}catch(e){if(token===epoch){if(e.status===409){try{const r=await cloud.cafe({action:'join'});if(token===epoch){paint(r);message('已重新回到咖啡馆')}}catch{message('正在重新连接…')}}else message('正在重新连接…')}}finally{syncing=false}}
 async function open(){if(active||opening)return;if(!cloud){toast('登录后就可以和大家一起去咖啡馆');return}opening=true;try{if(!await cloud.flush())return;const r=await cloud.cafe({action:'join'});beforeOpen();document.querySelector('#world-menu')?.close();active=true;epoch++;document.body.classList.add('in-cafe');shell.hidden=false;scene=createCafeScene(shell.querySelector('.cafe-stage'),{onPick:pick,onMove:v=>pose=v,onError:message});paint(r);scene.focus('exterior');sessionStorage.setItem('echoo-cafe-open','1');timer=setInterval(sync,750);await scene.ready;message('拖动看海，双指缩放 · 点座位坐下')}catch(e){toast(e.message||'咖啡馆暂时没能打开');await close()}finally{opening=false}}
 async function close(){const had=active;active=false;epoch++;clearInterval(timer);clearTimeout(noteTimer);scene?.dispose();scene=null;shell.hidden=true;actions.hidden=true;selection=null;pendingOrder=null;busy=false;document.body.classList.remove('in-cafe');sessionStorage.removeItem('echoo-cafe-open');if(had){try{await cloud.cafe({action:'leave'})}catch{}onClose?.();await cloud.refresh()}}
 async function walk(x,z,done){const mine=data?.guests.find(g=>g.id===data.self);if(mine?.seat&&!await action({action:'stand'}))return;scene.routeTo(x,z,done)}
 function pick(p,point){actions.hidden=true;selection=null;if(p.type==='enter'){scene.focus('inside');walk(0,2.9);return}if(p.type==='ground'){walk(point.x,point.z);return}if(p.type==='seat'){const s=cafeSeats.find(s=>s.id===p.value);walk(s.approachX??s.x,s.approachZ??s.z+.58,()=>void action({action:'seat',seat:s.id}));return}if(p.type==='drinks'){scene.focus('bar');menu();return}if(p.type==='item'){choose(p.value)}}
 function menu(){selection=null;show('<div class="cafe-menu">'+cafeMenu.filter(i=>i.kind!=='dessert').map(i=>`<button data-item="${i.id}">${i.name}</button>`).join('')+'</div>')}
 function choose(id){const item=cafeMenu.find(i=>i.id===id);if(!item)return;selection=id;show(`<strong>${item.name}</strong><div><button data-order="here">${item.kind==='dessert'?'在这吃':'在这喝'}</button><button data-order="takeaway">带走</button></div>`)}
 shell.addEventListener('click',async e=>{const order=e.target.closest('[data-order]'),item=e.target.closest('[data-item]'),button=e.target.closest('[data-cafe]');if(item){choose(item.dataset.item);return}if(order&&selection){if(!pendingOrder||pendingOrder.item!==selection||pendingOrder.mode!==order.dataset.order)pendingOrder={action:'order',item:selection,mode:order.dataset.order,command:newId()};order.disabled=true;const r=await action(pendingOrder);order.disabled=false;if(r){pendingOrder=null;selection=null;actions.hidden=true;message(r.takeaway?'已打包，放进你家冰箱了':'主理人正在准备，稍等一下');if(r.takeaway)await cloud.refresh()}return}if(!button)return;switch(button.dataset.cafe){case'leave':await close();break;case'island':actions.hidden=true;selection=null;scene.focus('island');break;case'terrace':actions.hidden=true;selection=null;scene.focus('terrace');break;case'inside':actions.hidden=true;selection=null;note.textContent='';scene.focus('inside');break;case'drinks':scene.focus('bar');menu();break;case'desserts':selection=null;actions.hidden=true;scene.focus('desserts');message('点柜中的甜品');break;case'eat':if(await action({action:'eat'})){actions.hidden=true;message('慢慢享用，吹一会儿海风')}break;}});
 entry.onclick=open;document.addEventListener('visibilitychange',()=>{if(!document.hidden)void sync()});
 window.addEventListener('pagehide',()=>{if(active)fetch('/api/cafe',{method:'POST',keepalive:true,headers:{'Content-Type':'application/json','X-CSRF-Token':cloud.session.csrf,'X-Planet-Space':String(cloud.session.space)},body:JSON.stringify({action:'leave'})}).catch(()=>{})});
 if(sessionStorage.getItem('echoo-cafe-open')==='1')setTimeout(open,500);
 return {open,close,get active(){return active},state:()=>({active,room:data?.room,guests:data?.guests,scene:scene?.state()})};
}
